        children: "import java.util.*;

final class BfsResult {
    final int source;
    final int[] dist;
    final int[] parent;
    final int[] order;

    BfsResult(int source, int[] dist, int[] parent, int[] order) {
        this.source = source;
        this.dist = dist;
        this.parent = parent;
        this.order = order;
    }

    boolean reachable(int v) {
        return dist[v] >= 0;
    }

    List<Integer> pathTo(int target) {
        if (!reachable(target)) return List.of();
        ArrayList<Integer> path = new ArrayList<>();
        for (int cur = target; cur != -1; cur = parent[cur]) {
            path.add(cur);
        }
        Collections.reverse(path);
        return path;
    }
}

final class GraphTraversal {
    static BfsResult bfs(IntGraph g, int source) {
        int n = g.size();
        if (source < 0 || source >= n) {
            throw new IndexOutOfBoundsException("invalid source: " + source);
        }

        int[] dist = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dist, -1);
        Arrays.fill(parent, -1);

        int[] order = new int[n];
        int orderSize = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[source] = 0;
        q.addLast(source);

        while (!q.isEmpty()) {
            int u = q.removeFirst();
            order[orderSize++] = u;

            for (int v : g.neighbors(u)) {
                if (dist[v] != -1) continue;
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.addLast(v);
            }
        }

        return new BfsResult(source, dist, parent, Arrays.copyOf(order, orderSize));
    }
}
