        className: "language-java",
        children: "static List<Integer> shortestPathUnweighted(IntGraph g, int source, int target) {
    int n = g.size();
    int[] dist = new int[n];
    int[] parent = new int[n];
    Arrays.fill(dist, -1);
    Arrays.fill(parent, -1);

    ArrayDeque<Integer> q = new ArrayDeque<>();
    dist[source] = 0;
    q.addLast(source);

    while (!q.isEmpty()) {
        int u = q.removeFirst();
        if (u == target) break;

        for (int v : g.neighbors(u)) {
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            parent[v] = u;
            if (v == target) {
                return reconstructPath(parent, source, target);
            }
            q.addLast(v);
        }
    }

    if (dist[target] == -1) return List.of();
    return reconstructPath(parent, source, target);
}

private static List<Integer> reconstructPath(int[] parent, int source, int target) {
    ArrayList<Integer> path = new ArrayList<>();
    for (int cur = target; cur != -1; cur = parent[cur]) {
        path.add(cur);
        if (cur == source) break;
    }
    Collections.reverse(path);
    return path;
}
