        className: "language-java",
        children: "static int bidirectionalBfs(IntGraph g, int source, int target) {
    if (source == target) return 0;

    int n = g.size();
    int[] distA = new int[n];
    int[] distB = new int[n];
    Arrays.fill(distA, -1);
    Arrays.fill(distB, -1);

    ArrayDeque<Integer> qa = new ArrayDeque<>();
    ArrayDeque<Integer> qb = new ArrayDeque<>();

    distA[source] = 0;
    distB[target] = 0;
    qa.addLast(source);
    qb.addLast(target);

    while (!qa.isEmpty() && !qb.isEmpty()) {
        int ans;
        if (qa.size() <= qb.size()) {
            ans = expandOneLayer(g, qa, distA, distB);
        } else {
            ans = expandOneLayer(g, qb, distB, distA);
        }
        if (ans != -1) return ans;
    }

    return -1;
}

private static int expandOneLayer(IntGraph g, ArrayDeque<Integer> q,
                                  int[] ownDist, int[] otherDist) {
    int layerSize = q.size();
    while (layerSize-- > 0) {
        int u = q.removeFirst();
        for (int v : g.neighbors(u)) {
            if (ownDist[v] != -1) continue;
            ownDist[v] = ownDist[u] + 1;
            if (otherDist[v] != -1) {
                return ownDist[v] + otherDist[v];
            }
            q.addLast(v);
        }
    }
    return -1;
}
